/* From Uiverse.io by garerim - Tags: card */
.__UIV_SCOPE__ .card {
  position: relative;
  width: 190px;
  height: 254px;
  background: #fff;
  border: solid 4px #333;
  box-shadow: -5px 5px #333;
  transition: all .2s ease-in-out;
  display: flex;
  justify-content: center;
  cursor: pointer;
}

.__UIV_SCOPE__ .card:hover {
  margin: 10px 10px 0 0;
  box-shadow: 0px 0px #333;
}

.__UIV_SCOPE__ .card .img-card {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: calc(100% - 50px);
  display: flex;
  justify-content: center;
  align-items: center;
  transition: filter .2s 1s ease-in-out;
}

.__UIV_SCOPE__ .card:hover .img-card {
  filter: blur(1px);
}

.__UIV_SCOPE__ .card .add-cart {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: calc(100% - 50px);
  background-color: rgba(0, 0, 0, 0.1);
  text-align: center;
  line-height: 250px;
  font-weight: bold;
  font-size: 19px;
  opacity: 0;
}

.__UIV_SCOPE__ .card:hover .add-cart {
  opacity: 1;
  transition: opacity .3s 1s ease-in-out;
}

.__UIV_SCOPE__ .card .info-card {
  position: absolute;
  height: 50px;
  width: 100%;
  bottom: 0;
  left: 0;
  right: 0;
  border-top: solid 1px #333;
}

.__UIV_SCOPE__ .card .info-card p {
  font-size: 14px;
  margin: 5px;
}
